    """
    Check whether the words follow the same pattern as the patterns array.

    Two strings follow the same pattern if there exists a bijection between
    the characters of one and the characters of the other such that:
    - Each character in one string maps to a character in the other
    - The mapping is one-to-one (no two different characters map to the same character)

    Args:
        words: A list of strings representing the words.
        patterns: A list of strings representing the patterns.

    Returns:
        True if the words follow the same pattern as the patterns, False otherwise.
    """
    if len(words) != len(patterns):
        return False

    for word, pattern in zip(words, patterns):
        if len(word) != len(pattern):
            return False

        # Check if there's a valid bijection between word characters and pattern characters
        word_to_pattern = {}
        pattern_to_word = {}

        for w_char, p_char in zip(word, pattern):
            if w_char in word_to_pattern:
                if word_to_pattern[w_char] != p_char:
                    return False
            else:
                word_to_pattern[w_char] = p_char

            if p_char in pattern_to_word:
                if pattern_to_word[p_char] != w_char:
                    return False
            else:
                pattern_to_word[p_char] = w_char

    return True

