def search(nums: list[int]) -> int:
    """
    Find the element that appears only once in a sorted array where every other element appears exactly twice.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        # If mid is odd, its pair should be mid-1
        # If mid is even, its pair should be mid+1
        if mid % 2 == 1:
            compare_with = mid - 1
        else:
            compare_with = mid + 1

        if nums[mid] == nums[compare_with]:
            # The single element is to the right of mid
            left = mid + 1
        else:
            # The single element is at mid or to the left
            right = mid

    return nums[left]

def search(arr: list[int]) -> int:
    """
    Find the element that appears only once in a sorted array where all other elements appear exactly twice.

    Args:
        arr: A sorted list of integers where all elements appear exactly twice except one.

    Returns:
        The element that appears only once.
    """
    n = len(arr)

    if n == 0:
        raise ValueError("Array is empty")
    if n == 1:
        return arr[0]

    left, right = 0, n - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is the unique element
        if mid == 0 or arr[mid - 1] != arr[mid]:
            if mid == n - 1 or arr[mid + 1] != arr[mid]:
                return arr[mid]

        # If the left side has an even number of elements, the unique element is on the left
        if mid % 2 == 0:
            if mid > 0 and arr[mid - 1] == arr[mid]:
                right = mid - 2
            else:
                left = mid + 1
        else:
            # mid is odd
            if mid > 0 and arr[mid - 1] == arr[mid]:
                left = mid + 1
            else:
                right = mid - 1

    return arr[left]

