def newman_prime(n: int) -> int:
    """
    Find the nth Newman-Shanks-Williams (NSW) prime number.

    NSW numbers are defined by the recurrence relation:
    N_1 = 1, N_2 = 3
    N_k = 2 * N_{k-1} + N_{k-2} for k > 2

    We need to find the nth prime number among the NSW numbers.
    """
    def is_prime(num: int) -> bool:
        """Check if a number is prime."""
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        if num == 3:
            return True
        if num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    # Generate NSW numbers and check for primality
    count = 0
    a, b = 1, 3  # N_1, N_2

    # Check N_1
    if is_prime(a):
        count += 1
        if count == n:
            return a

    # Check N_2
    if is_prime(b):
        count += 1
        if count == n:
            return b

    # Generate subsequent NSW numbers
    while True:
        a, b = b, 2 * b + a
        if is_prime(b):
            count += 1
            if count == n:
                return b

