import math

def count_binary_seq(n):
    """
    Find the count of all binary sequences of length 2n such that 
    the sum of first n bits is the same as the sum of last n bits.

    The count is C(2n, n). For large n, we use logarithms to avoid
    slow big-integer arithmetic.
    """
    if n == 0:
        return 1.0

    # Use lgamma to compute log(C(2n, n)) = lgamma(2n+1) - lgamma(n+1) - lgamma(n+1)
    log_val = math.lgamma(2 * n + 1) - 2 * math.lgamma(n + 1)

    # For small n, we can return the exact integer as a float
    # For large n, return the float approximation
    if n <= 1000:
        # Return exact value as float for small n to ensure precision
        from math import comb
        return float(comb(2 * n, n))
    else:
        return math.exp(log_val)

def dict_depth(d):
    """
    Find the depth of a dictionary.

    The depth is defined as the maximum number of nested dictionary levels.
    An empty dictionary has depth 0.
    A non-empty dictionary with no nested dictionaries has depth 1.
    """
    if not isinstance(d, dict):
        return 0

    if not d:
        return 0

    max_depth = 0
    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth(value) + 1
            if depth > max_depth:
                max_depth = depth
        else:
            # Non-dict values don't add depth, but the current dict itself adds 1
            if max_depth == 0:
                max_depth = 1

    # If max_depth is still 0, it means all values are non-dicts, so depth is 1
    if max_depth == 0:
        return 1

    return max_depth

