def set_left_most_unset_bit(n: int) -> int:
    """
    Set the left most unset bit (highest-order 0 bit) in the binary representation of n.
    Returns the new integer with that bit set.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return 1

    highest_set_bit = n.bit_length() - 1

    for pos in range(highest_set_bit, -1, -1):
        if not (n & (1 << pos)):
            return n | (1 << pos)

    # All bits from highest_set_bit down to 0 are set
    # The leftmost unset bit is at position highest_set_bit + 1
    return n | (1 << (highest_set_bit + 1))

def set_left_most_unset_bit(n: int) -> int:
    """
    Set the left most unset bit (highest-order 0 bit) in the binary representation of n.
    Returns the new integer with that bit set.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        # All bits are unset. The leftmost unset bit is at position 0.
        return 1

    # For n > 0, the leftmost unset bit is the first 0 bit when scanning
    # from the most significant bit position (highest_set_bit) down to bit 0.
    # But we also need to consider that if all bits up to highest_set_bit are set,
    # then the leftmost unset bit is at position highest_set_bit + 1.

    highest_set_bit = n.bit_length() - 1

    # Scan from highest_set_bit down to 0
    for pos in range(highest_set_bit, -1, -1):
        if not (n & (1 << pos)):
            return n | (1 << pos)

    # All bits from highest_set_bit down to 0 are set
    return n | (1 << (highest_set_bit + 1))

def convert_list_dictionary(list1, list2, list3):
    """
    Convert three lists into a list of nested dictionaries.

    Args:
        list1: List of outer keys
        list2: List of inner keys
        list3: List of values

    Returns:
        A list of nested dictionaries where each dictionary has the structure:
        {outer_key: {inner_key: value}}
    """
    return [
        {key1: {key2: value}}
        for key1, key2, value in zip(list1, list2, list3)
    ]

