def max_product(arr):
    """
    Find the maximum product formed by multiplying numbers of an increasing subsequence of the array.

    An increasing subsequence means the values are strictly increasing.
    The subsequence must be non-empty.
    """
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] = max product of an increasing subsequence ending at index i
    # For each i, we look at all j < i where arr[j] < arr[i]
    # dp[i] = max(arr[i], max(dp[j] * arr[i] for all valid j))

    dp = [0] * n

    for i in range(n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                # We can extend the subsequence ending at j with arr[i]
                product = dp[j] * arr[i]
                if product > dp[i]:
                    dp[i] = product

    return max(dp)

