def last_Digit_Factorial(n: int) -> int:
    """
    Find the last digit of n!.

    For n >= 5, n! contains both factor 2 and factor 5, so n! is divisible by 10,
    meaning the last digit is 0.
    For n < 5, we can compute directly.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 5:
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result % 10
    else:
        return 0

