def largest_subset(nums):
    """
    Find the size of the largest subset of a list of numbers so that every pair is divisible
    (i.e., for any two elements a and b in the subset, a divides b or b divides a).
    """
    if not nums:
        return 0

    # Remove zeros and track if any exist
    has_zero = False
    non_zero = []
    for num in nums:
        if num == 0:
            has_zero = True
        else:
            non_zero.append(num)

    if not non_zero:
        # All zeros
        return 1 if has_zero else 0

    # Sort the non-zero numbers
    sorted_nums = sorted(non_zero)
    n = len(sorted_nums)

    # dp[i] = length of the longest divisible subset ending at sorted_nums[i]
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            # Check if sorted_nums[j] divides sorted_nums[i]
            if sorted_nums[i] % sorted_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    max_chain = max(dp)

    # If zero exists, we can add it to any valid chain since 0 % x == 0 for any non-zero x
    if has_zero:
        max_chain += 1

    return max_chain

