def get_median(list1, list2, n):
    """
    Find the median of two sorted lists of same size.

    Args:
        list1: First sorted list
        list2: Second sorted list
        n: Size of each list

    Returns:
        The median of the combined sorted elements
    """
    # Use binary search approach for O(log n) time complexity
    if n == 0:
        return 0.0

    # Ensure list1 is the smaller or equal size (they should be equal, but just in case)
    if len(list1) > len(list2):
        list1, list2 = list2, list1
        n1, n2 = len(list1), len(list2)
    else:
        n1, n2 = len(list1), len(list2)

    if n1 == 0:
        if n2 % 2 == 0:
            return (list2[n2 // 2 - 1] + list2[n2 // 2]) / 2.0
        else:
            return float(list2[n2 // 2])

    imin, imax = 0, n1
    half = (n1 + n2 + 1) // 2

    while imin <= imax:
        i = (imin + imax) // 2
        j = half - i

        if i < n1 and list2[j - 1] > list1[i]:
            # i is too small, go higher
            imin = i + 1
        elif i > 0 and list1[i - 1] > list2[j]:
            # i is too big, go lower
            imax = i - 1
        else:
            # i is perfect
            if i == 0:
                max_of_left = list2[j - 1]
            elif j == 0:
                max_of_left = list1[i - 1]
            else:
                max_of_left = max(list1[i - 1], list2[j - 1])

            if (n1 + n2) % 2 == 1:
                return float(max_of_left)

            if i == n1:
                min_of_right = list2[j]
            elif j == n2:
                min_of_right = list1[i]
            else:
                min_of_right = min(list1[i], list2[j])

            return (max_of_left + min_of_right) / 2.0

    return 0.0

def get_coordinates(coord):
    """
    Extract all adjacent coordinates of the given coordinate tuple.
    Adjacent means within a neighborhood (including the coordinate itself).
    Works for 2D, 3D, etc. coordinates.
    """
    n = len(coord)
    result = []
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            if n == 2:
                result.append([coord[0] + dx, coord[1] + dy])
            elif n == 3:
                for dz in [-1, 0, 1]:
                    result.append([coord[0] + dx, coord[1] + dy, coord[2] + dz])
            else:
                # For higher dimensions, generate all combinations
                from itertools import product
                for deltas in product([-1, 0, 1], repeat=n):
                    result.append([coord[i] + deltas[i] for i in range(n)])
                break
    if n != 2 and n != 3:
        # Already handled in the loop above, but restructure to avoid duplication
        from itertools import product
        result = []
        for deltas in product([-1, 0, 1], repeat=n):
            result.append([coord[i] + deltas[i] for i in range(n)])
    return result

