def divisible_by_digits(startnum, endnum):
    """
    Find numbers within a given range [startnum, endnum] where every number
    is divisible by every digit it contains.

    Note: We ignore the digit 0 because division by zero is undefined.
    """
    result = []
    for num in range(startnum, endnum + 1):
        digits = [int(d) for d in str(num)]
        # Check if num is divisible by each non-zero digit
        valid = True
        for d in digits:
            if d == 0:
                continue
            if num % d != 0:
                valid = False
                break
        if valid:
            result.append(num)
    return result

def min_k(records, k):
    """
    Find minimum k records from a list of tuples based on the second element.
    If k is negative, it means take all records except the last |k| records
    after sorting by the second element.

    Returns a list of records.
    """
    if not records:
        return []

    # Sort the records by the second element
    sorted_records = sorted(records, key=lambda x: x[1])

    if k < 0:
        # Take all except the last |k| records
        if -k >= len(sorted_records):
            return []
        return sorted_records[:-k]
    elif k == 0:
        return []
    else:
        if k >= len(sorted_records):
            return sorted_records
        return sorted_records[:k]

def min_k(records, k):
    """
    Find minimum k records from a list of tuples.
    When k is positive, return the k smallest records (by second element).
    When k is negative, return all records except the last |k| smallest.
    """
    if not records:
        return []

    # Sort the records by the second element
    sorted_records = sorted(records, key=lambda x: x[1])

    if k > 0:
        if k >= len(sorted_records):
            return sorted_records
        return sorted_records[:k]
    else:
        # k is negative: take all records except the last |k|
        if -k >= len(sorted_records):
            return []
        return sorted_records[:-k]

