import math

def is_prime(n: int) -> bool:
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    if n == 3:
        return True
    if n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def newman_prime(n: int) -> int:
    """
    Find the nth Newman-Shanks-Williams (NSW) prime number.
    """
    # Generate NSW numbers: a(0)=0, a(1)=1, a(k) = 2*a(k-1) + a(k-2)
    # Collect primes from this sequence (1-indexed, skip a(0)=0 which is not prime)
    count = 0
    a0, a1 = 0, 1
    k = 0
    while True:
        if k >= 2:
            a = 2 * a1 + a0
            a0, a1 = a1, a
        else:
            a = a0 if k == 0 else a1

        if a >= 2 and is_prime(a):
            count += 1
            if count == n:
                return a
        k += 1

