def dict_depth(d):
    """
    Find the depth of a nested dictionary.

    Args:
        d: A (possibly nested) dictionary.

    Returns:
        The depth of the dictionary. An empty dict has depth 1.
        A dict with only non-dict values has depth 1.
        A dict with nested dicts has depth = 1 + max(nested dict depths).
    """
    if not isinstance(d, dict):
        return 1
    if len(d) == 0:
        return 1
    max_depth = 0
    for value in d.values():
        if isinstance(value, dict):
            depth = dict_depth(value)
        else:
            depth = 0
        if depth > max_depth:
            max_depth = depth
    return 1 + max_depth

