def min_k(records, k):
    if not records:
        return []
    if k == 0:
        return []
    if k < 0:
        # Return all records except the last |k| records
        return records[:len(records) + k]
    else:
        # Return the k smallest records by second element
        sorted_records = sorted(records, key=lambda x: x[1])
        return sorted_records[:k]

def tuple_str_int(s: str) -> tuple:
    """
    Convert a tuple string to an integer tuple.

    Args:
        s: A string representing a tuple, e.g., "(7, 8, 9)"

    Returns:
        A tuple of integers, e.g., (7, 8, 9)
    """
    s = s.strip()

    # Find the first '(' and last ')'
    first_paren = s.find('(')
    last_paren = s.rfind(')')

    if first_paren != -1 and last_paren != -1 and last_paren > first_paren:
        inner = s[first_paren + 1:last_paren]
    else:
        # Fallback: just use the whole string
        inner = s

    if not inner.strip():
        return ()

    # Split by comma and convert each element to int
    elements = []
    for x in inner.split(','):
        x = x.strip()
        if x:
            elements.append(int(x))

    return tuple(elements)

def tuple_str_int(s: str) -> tuple:
    """
    Convert a tuple string to an integer tuple.

    Args:
        s: A string representing a tuple, e.g., "(7, 8, 9)"

    Returns:
        A tuple of integers, e.g., (7, 8, 9)
    """
    s = s.strip()

    # Strip all leading '(' and trailing ')'
    while s.startswith('('):
        s = s[1:]
    while s.endswith(')'):
        s = s[:-1]

    s = s.strip()

    if not s:
        return ()

    # Split by comma and convert each element to int
    elements = []
    for x in s.split(','):
        x = x.strip()
        if x:
            elements.append(int(x))

    return tuple(elements)

